public enum QRErrorCorrectionLevel{

        LOW("11"),
        MEDIUM("10"),
        QUARTILE("01"),
        HIGH("00");

        private final String errorCorrectionId;

        QRErrorCorrectionLevel(String givenId){

            this.errorCorrectionId = givenId;
        }

        public String getErrorCorrectionId(){

            return this.errorCorrectionId;
        }
    }

//We can use the enum types as usual
private QRErrorCorrectionLevel correctionLevel = QRErrorCorrectionLevel.LOW;

//And if we want to retrive the value associated with it, we can do something like this
correctionLevel.getErrorCorrectionId();
